// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 管理精选缓存
	// (GET /v1/admin/cache)
	ListCacheEntries(w http.ResponseWriter, r *http.Request, params ListCacheEntriesParams)
	// 人工创建精选候选
	// (POST /v1/admin/cache)
	ProposeCacheEntry(w http.ResponseWriter, r *http.Request, params ProposeCacheEntryParams)
	// 缓存阈值校准
	// (GET /v1/admin/cache-calibration)
	ReadCacheCalibration(w http.ResponseWriter, r *http.Request, params ReadCacheCalibrationParams)
	// 批准缓存公开内容
	// (POST /v1/admin/cache/{cacheId}/approve)
	ApproveCacheEntry(w http.ResponseWriter, r *http.Request, cacheId Identifier, params ApproveCacheEntryParams)
	// 人工停用缓存
	// (POST /v1/admin/cache/{cacheId}/disable)
	DisableCacheEntry(w http.ResponseWriter, r *http.Request, cacheId Identifier, params DisableCacheEntryParams)
	// 隔离管理诊断
	// (POST /v1/admin/debug-turns)
	CreateDebugTurn(w http.ResponseWriter, r *http.Request, params CreateDebugTurnParams)
	// 读取管理诊断
	// (GET /v1/admin/debug-turns/{debugId})
	ReadDebugTurn(w http.ResponseWriter, r *http.Request, debugId Identifier, params ReadDebugTurnParams)
	// 读取问答策略
	// (GET /v1/admin/policy)
	ReadQaPolicy(w http.ResponseWriter, r *http.Request)
	// 管理公开问答策略
	// (PUT /v1/admin/policy)
	PutQaPolicy(w http.ResponseWriter, r *http.Request, params PutQaPolicyParams)
	// 浏览与筛选问答记录
	// (GET /v1/admin/turns)
	ListTurnRecords(w http.ResponseWriter, r *http.Request, params ListTurnRecordsParams)
	// 查看问答记录
	// (GET /v1/admin/turns/{turnId})
	ReadTurnRecord(w http.ResponseWriter, r *http.Request, turnId string)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request, params AcquireBarrierParams)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId TypesIdentifier, params ReleaseBarrierParams)
	// 创建伪名访客会话
	// (POST /v1/conversations)
	CreateConversation(w http.ResponseWriter, r *http.Request, params CreateConversationParams)
	// 删除自有对话数据
	// (DELETE /v1/conversations/{conversationId})
	DeleteConversation(w http.ResponseWriter, r *http.Request, conversationId Identifier, params DeleteConversationParams)
	// 读取自有访客历史
	// (GET /v1/conversations/{conversationId})
	GetConversation(w http.ResponseWriter, r *http.Request, conversationId Identifier, params GetConversationParams)
	// 读取缓存翻译的当前权威基准材料
	// (GET /v1/internal/cache/{cacheId}/translation-source)
	ReadCacheTranslationSource(w http.ResponseWriter, r *http.Request, cacheId Identifier)
	// 免费读取公开问答入口配置能力
	// (GET /v1/public-capabilities)
	ReadPublicCapability(w http.ResponseWriter, r *http.Request)
	// 访客全文搜索（关键词与向量混合检索）
	// (POST /v1/search)
	SearchDocuments(w http.ResponseWriter, r *http.Request, params SearchDocumentsParams)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(w http.ResponseWriter, r *http.Request, snapshotId Identifier, params ReadSnapshotArchiveParams)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request, params DiscardSnapshotParams)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request, params ExportSnapshotParams)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request, params StageSnapshotParams)
	// 准入后开始问答轮次
	// (POST /v1/turns)
	StartTurn(w http.ResponseWriter, r *http.Request, params StartTurnParams)
	// 取消问答及所有子调用
	// (POST /v1/turns/{turnId}/cancel)
	CancelTurn(w http.ResponseWriter, r *http.Request, turnId Identifier, params CancelTurnParams)
	// SSE断线重连
	// (GET /v1/turns/{turnId}/events)
	ResumeAnswerStream(w http.ResponseWriter, r *http.Request, turnId Identifier, params ResumeAnswerStreamParams)
	// 保存访客单条反馈
	// (PUT /v1/turns/{turnId}/feedback)
	RecordFeedback(w http.ResponseWriter, r *http.Request, turnId Identifier, params RecordFeedbackParams)
}

